import Foundation
import UIKit



class PokemonManager {

    /// Name of the index generated by build_index.py (no "_" so it is never mistaken for a Pokemon file)
    static let indexFileName = "pokedex-index"

    /// Reads pokedex-index.json. Returns an empty dictionary if the index is missing or invalid,
    /// in which case the app falls back on reading the full Pokemon files.
    func loadIndex() -> [String: PokemonIndexEntry] {
        guard let url = Bundle.main.url(forResource: Self.indexFileName, withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let entries = try? JSONDecoder().decode([PokemonIndexEntry].self, from: data) else {
            print("Index not found or invalid: run build_index.py")
            return [:]
        }
        return Dictionary(entries.map { ($0.file, $0) }, uniquingKeysWith: { first, _ in first })
    }

    /// Lists the Pokemon files of the bundle ("<dex number>_<name>.json"), sorted by Pokedex number.
    /// The files are the source of truth; the index only adds names, generation, types and stats.
    func getPokemon(index: [String: PokemonIndexEntry]) -> [Pokemon] {
        // Get all the JSON files of the bundle
        guard let resourcePath = Bundle.main.resourcePath else {
            print("Could not find resource path")
            return []
        }

        let fileManager = FileManager.default
        var pokemonList: [Pokemon] = []

        // Read all the files of the bundle
        if let files = try? fileManager.contentsOfDirectory(atPath: resourcePath) {
            for file in files where file.hasSuffix(".json") {
                // Extract the Pokedex number and the name of the file (ex: "025_pikachu.json")
                let fileName = file.replacingOccurrences(of: ".json", with: "")
                let components = fileName.split(separator: "_")

                if components.count == 2,
                   let dexNumber = Int(components[0]) {
                    let name = String(components[1])
                    let entry = index[fileName]
                    let pokemon = Pokemon(
                        fileName: fileName,
                        dexNumber: dexNumber,
                        name: name,
                        displayName: entry?.nameEn ?? name.capitalized,
                        generation: entry?.generation ?? PokemonManager.generation(dexNumber: dexNumber, name: name)
                    )
                    pokemonList.append(pokemon)
                }
            }
        }

        // Sort by Pokedex number, a regional form right after its base species
        return pokemonList.sorted { ($0.dexNumber, $0.fileName) < ($1.dexNumber, $1.fileName) }
    }

    /// Generation when the index is missing: from the regional suffix, else from the Pokedex number
    static func generation(dexNumber: Int, name: String) -> Int {
        if name.hasSuffix("-alola") { return 7 }
        if name.contains("-galar") || name.hasSuffix("-hisui") { return 8 }
        return PokemonGeneration.from(pokemonId: dexNumber)?.rawValue ?? 0
    }

    func getDetailedPokemon(fileName: String) -> DetailPokemon? {
        return Bundle.main.decodeOptional(file: fileName)
    }

    func getSprite(for pokemon: Pokemon) -> UIImage? {
        return Bundle.main.image(file: pokemon.fileName)
    }
}
